def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Find first position where they differ
    min_len = min(len(s_in), len(s_out))

    # Check for character substitutions
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if we're replacing a substring
            # For now, let's assume single character changes
            return (s_in[i], s_out[i], i)

    # If we reach here, one string is prefix of another
    if len(s_in) < len(s_out):
        # Insertion
        return (s_in[-1], s_out[len(s_in)], len(s_in) - 1) if len(s_in) > 0 else (None, s_out[0], 0)
    elif len(s_in) > len(s_out):
        # Deletion
        return (s_in[len(s_out)], '', len(s_out))
    else:
        # Strings are identical
        return ('', '', -1)

def propose_rule_candidates(s_in, s_out):
    """Propose candidates for replacement rules"""
    # Simple approach: look for patterns that could explain the transformation
    candidates = []

    # Single character replacements
    min_len = min(len(s_in), len(s_out))
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            candidates.append((s_in[i], s_out[i]))

    # Look for longer patterns if possible
    # Check for substring matches
    for length in range(3, 0, -1):  # Check lengths 3, 2, 1
        if len(s_in) >= length:
            pattern = s_in[:length]
            if pattern in s_out:
                # See if we can find a replacement
                pos = s_out.find(pattern)
                if pos != -1:
                    # Calculate what should replace this pattern
                    replacement = s_out[pos:pos+length]
                    if replacement != pattern:
                        candidates.append((pattern, replacement))

    # Return unique candidates
    seen = set()
    unique_candidates = []
    for cand in candidates:
        if cand not in seen:
            seen.add(cand)
            unique_candidates.append(cand)

    return unique_candidates

