# Implementing basic analysis functions based on the prompt guidelines

def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings."""
    # Find first position where they differ
    min_len = min(len(s_in), len(s_out))

    for i in range(min_len):
        if s_in[i] != s_out[i]:
            return (s_in[i], s_out[i], i)

    # If we reach here, one string is prefix of another
    if len(s_in) < len(s_out):
        # Insertion at end
        return (s_in[-1] if len(s_in) > 0 else '', s_out[len(s_in)], len(s_in))
    elif len(s_in) > len(s_out):
        # Deletion at end  
        return (s_in[len(s_out)], '', len(s_out))
    else:
        return ('', '', -1)

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a changed pair."""
    candidates = []

    # Start with most specific: single character replacements
    min_len = min(len(s_in), len(s_out))
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            candidates.append((s_in[i], s_out[i]))

    # Also consider longer patterns if they exist
    # Check substrings of length 2 and 3
    for length in [3, 2]:
        if len(s_in) >= length:
            pattern = s_in[:length]
            if pattern in s_out:
                pos = s_out.find(pattern)
                if pos != -1:
                    replacement = s_out[pos:pos+length]
                    if replacement != pattern:
                        candidates.append((pattern, replacement))

    # Remove duplicates while preserving order
    seen = set()
    unique_candidates = []
    for cand in candidates:
        if cand not in seen:
            seen.add(cand)
            unique_candidates.append(cand)

    return unique_candidates

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules match the input/output pairs."""
    result = apply_rules(inputs, rules)
    correct = sum(1 for i, o in zip(result, outputs) if i == o)
    return correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find examples where rules incorrectly modify strings that should remain unchanged."""
    result = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, res) in enumerate(zip(inputs, outputs, result)):
        if inp != outp and inp == res:
            # The input should have changed but didn't
            pass
        elif inp != outp and res != outp:
            # The input changed but not correctly
            pass
        elif inp == outp and res != outp:
            # The input was supposed to stay the same but got changed
            over_apps.append((i, inp, res))
    return over_apps

